// AppendZoo appends the JSON encoding of v to dst.
func AppendZoo(dst []byte, v *Zoo) ([]byte, error) {
	return v.odjsonAppend(dst, odjsonrt.ModeHTML)
}

// odjsonSizeZoo sizes the buffer MarshalZoo allocates.
var odjsonSizeZoo odjsonrt.SizeHint

// MarshalZoo returns the JSON encoding of v.
func MarshalZoo(v *Zoo) ([]byte, error) {
	buf, err := v.odjsonAppend(odjsonSizeZoo.New(), odjsonrt.ModeHTML)
	if err != nil {
		return nil, err
	}
	odjsonSizeZoo.Record(buf)
	return buf, nil
}

// UnmarshalZoo decodes the JSON document data into v.
func UnmarshalZoo(data []byte, v *Zoo) error {
	p, err := v.odjsonParse(data, odjsonrt.SkipSpace(data, 0))
	if err != nil {
		return err
	}
	return odjsonrt.EndOfDocument(data, p)
}

// MarshalJSON implements encoding/json.Marshaler.
func (v Zoo) MarshalJSON() ([]byte, error) {
	return MarshalZoo(&v)
}

// UnmarshalJSON implements encoding/json.Unmarshaler.
func (v *Zoo) UnmarshalJSON(data []byte) error {
	return UnmarshalZoo(data, v)
}

// MarshalJSONTo implements encoding/json/v2.MarshalerTo.
func (v Zoo) MarshalJSONTo(enc *jsontext.Encoder) error {
	// WriteValue copies what it is given, so the scratch buffer can go
	// straight back to the pool. ModeStream leaves the HTML escaping and
	// the UTF-8 validation to the encoder, which performs both while
	// reformatting the value either way.
	buf := odjsonrt.GetBuffer()
	var err error
	if buf.B, err = v.odjsonAppend(buf.B, odjsonrt.ModeStream); err == nil {
		odjsonSizeZoo.Record(buf.B)
		err = enc.WriteValue(buf.B)
	}
	odjsonrt.PutBuffer(buf)
	return err
}

// UnmarshalJSONFrom implements encoding/json/v2.UnmarshalerFrom.
func (v *Zoo) UnmarshalJSONFrom(dec *jsontext.Decoder) error {
	return v.odjsonParseFrom(dec)
}
